      "name": "RelSeries.head",
      "module_name": "Mathlib.Order.RelSeries",
      "kind": "definition",
      "type": "{α : Type u_1} → {r : SetRel α α} → RelSeries r → α"
    },
    {
      "name": "Set.seq_of_forall_finite_exists",
      "module_name": "Mathlib.Data.Set.Finite.Basic",
      "kind": "theorem",
      "type": "∀ {γ : Type u_1} {P : γ → Set γ → Prop},\n  (∀ (t : Set γ), t.Finite → ∃ c, P c t) → ∃ u, ∀ (n : ℕ), P (u n) (u '' Set.Iio n)"
    },
    {
      "name": "RelSeries.rec",
      "module_name": "Mathlib.Order.RelSeries",
      "kind": "recursor",
      "type": "{α : Type u_1} →\n  {r : SetRel α α} →\n    {motive : RelSeries r → Sort u} →\n      ((length : ℕ) →\n          (toFun : Fin (length + 1) → α) →\n            (step : ∀ (i : Fin length), (toFun i.castSucc, toFun i.succ) ∈ r) →\n              motive { length := length, toFun := toFun, step := step }) →\n        (t : RelSeries r) → motive t"
    },
    {
      "name": "RelSeries.recOn",
      "module_name": "Mathlib.Order.RelSeries",
      "kind": "definition",
      "type": "{α : Type u_1} →\n  {r : SetRel α α} →\n    {motive : RelSeries r → Sort u} →\n      (t : RelSeries r) →\n        ((length : ℕ) →\n            (toFun : Fin (length + 1) → α) →\n              (step : ∀ (i : Fin length), (toFun i.castSucc, toFun i.succ) ∈ r) →\n                motive { length := length, toFun := toFun, step := step }) →\n          motive t"
    },
    {
      "name": "exists_seq_of_forall_finset_exists'",
      "module_name": "Mathlib.Data.Fintype.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_4} (P : α → Prop) (r : α → α → Prop) [Std.Symm r],\n  (∀ (s : Finset α), (∀ x ∈ s, P x) → ∃ y, P y ∧ ∀ x ∈ s, r x y) →\n    ∃ f, (∀ (n : ℕ), P (f n)) ∧ Pairwise (Function.onFun r f)"
    }
  ]
}
